"min":45}}]},{"title":"Rôti de porc à la moutarde","intro":"Un rôti tout doux, avec une sauce moutarde à la crème.","minutes":80,"calories":580,"difficulty":"Facile","imageSearch":"pork roast mustard sauce","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"unit":"g","have":false},{"name":"moutarde","plural":"moutarde","qty":3,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Badigeonne le rôti de 2 c. à s. de moutarde, sale et poivre.","timer":null},{"text":"Mets-le dans un plat avec l'oignon émincé, le vin et un filet d'huile. Enfourne 1 h.","timer":{"label":"Four","min":60}},{"text":"Verse le jus dans une casserole avec la crème et le reste de moutarde, et laisse épaissir 3 min.","timer":{"label":"Sauce","min":3}}],"kids":true},{"title":"Porc au caramel express","intro":"Le porc au caramel pour un soir de semaine.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"quick caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":1,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gous