insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('jambon', 'jambon', array[]::text[], 'list', $r$[{"title":"Endives au jambon","intro":"Des endives fondantes roulées dans du jambon, gratinées sous une béchamel.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"endives ham gratin bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"endive","plural":"endives","qty":8,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":8,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les endives 20 min à la vapeur ou dans l'eau, puis presse-les bien pour les égoutter.","timer":{"label":"Cuisson","min":20}},{"text":"Fais une béchamel : beurre fondu, farine, puis lait en fouettant 5 min. Ajoute muscade, sel et poivre.","timer":{"label":"Béchamel","min":5}},{"text":"Préchauffe le four à 200 °C. Roule chaque endive dans une tranche de jambon et range-les dans un plat.","timer":null},{"text":"Nappe de béchamel et parsème d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true},{"title":"Calzone","intro":"La pizza pliée en chausson, garnie de jambon, mozzarella, champignons et œuf.","minutes":100,"calories":700,"difficulty":"Moyen","imageSearch":"calzone","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"farine","plural":"farines","qty":300,"unit":"g","have":false},{"name":"levure de boulanger","plural":"levure de boulanger","qty":7,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"coulis de tomate","plural":"coulis de tomate","qty":15,"unit":"cl","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":2,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":3,"unit":"tranches","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Prépare la pâte à pizza et laisse-la lever 1 h.","timer":{"label":"Levée","min":60}},{"text":"Préchauffe le four à 240 °C. Partage la pâte en 2 disques.","timer":null},{"text":"Garnis une moitié de chaque disque de coulis, de jambon, de champignons et de mozzarella, et casse un œuf.","timer":null},{"text":"Replie et soude les bords.","timer":null},{"text":"Enfourne 18 min.","timer":{"label":"Four","min":18}}],"kids":true},{"title":"Croque-monsieur","intro":"Le croque doré et fondant, avec du jambon, de l'emmental et une touche de béchamel.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"croque monsieur ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivr